package io.baozhu.atlas; import io.baozhu.atlas.domain.*; import org.junit.jupiter.api.Test; import java.util.*; import static org.assertj.core.api.Assertions.*;
class DomainTests { @Test void detectsCycle(){var a=new TaskDefinition("a","A",TaskType.SQL,List.of("b"),Map.of(),0);var b=new TaskDefinition("b","B",TaskType.SQL,List.of("a"),Map.of(),0);var p=new PipelineDefinition("x","X","1",List.of(a,b),Map.of());var result=DagValidator.validate(p);assertThat(result.valid()).isFalse();assertThat(result.errors()).anyMatch(x->x.contains("cycle"));} @Test void evaluatesQuality(){var rows=List.of(Map.<String,Object>of("id",1,"amount",2),Map.<String,Object>of("id",1,"amount",-3));var out=new QualityEvaluator().evaluate(rows,List.of(new QualityRule("id",QualityRuleType.UNIQUE,null,QualitySeverity.ERROR),new QualityRule("amount",QualityRuleType.NON_NEGATIVE,null,QualitySeverity.WARN)));assertThat(out).extracting(QualityResult::passed).containsExactly(false,false);} }
